fn run_fragment<'ctx>(
    context: &'ctx SiriusContext,
    parked: &mut HashMap<u64, ParkedOutput<'ctx>>,
    parked_slots: &mut HashMap<SenderSlot, (u64, u64)>,
    poisoned: &HashMap<SenderSlot, String>,
    next_park_id: &mut u64,
    request: &ExecuteRequest,
) -> Result<Option<FragmentResult>, String> {
    // Every engine-thread line of this run (relay, remote push, cardinality, lease sweep) carries
    // the StarRocks ids; the span's close event is the engine-side elapsed time of the run.
    let span = tracing::info_span!(
        "fragment",
        query_id = tracing::field::Empty,
        fragment_instance_id = tracing::field::Empty
    );
    if let Some(id) = request.label.query_id {
        span.record("query_id", tracing::field::display(id));
    }
    if let Some(id) = request.label.fragment_instance_id {
        span.record("fragment_instance_id", tracing::field::display(id));
    }
    let _entered = span.enter();
    let mut released = std::collections::HashSet::new();
    let result = run_fragment_inner(
        context,
        parked,
        parked_slots,
        poisoned,
        next_park_id,
        request,
        &mut released,
    );
    if result.is_err() {
        for (_, _, batches) in &request.remote_inputs {
            for batch in batches {
                // `len == 0` batches never held a lease (metadata-only), and offsets in
                // `released` already went back in the push loop.
                if batch.len == 0 || released.contains(&batch.offset) {
                    continue;
                }
                if let Err(err) = context.staging_release(batch.offset) {
                    warn!(
                        offset = batch.offset,
                        error = %err,
                        "failed to release a remote-input staging lease after a fragment error"
                    );
                }
            }
        }
    }
    result
}

/// Runs one fragment on the engine thread: declare its input streams, relay every parked sender
/// and push every staged remote batch into them, execute, then either park the output or return
/// the rows. Records each released remote-input lease offset in `released`.
fn run_fragment_inner<'ctx>(
    context: &'ctx SiriusContext,
    parked: &mut HashMap<u64, ParkedOutput<'ctx>>,
    parked_slots: &mut HashMap<SenderSlot, (u64, u64)>,
    poisoned: &HashMap<SenderSlot, String>,
    next_park_id: &mut u64,
    request: &ExecuteRequest,
    released: &mut std::collections::HashSet<u64>,
) -> Result<Option<FragmentResult>, String> {
    let mut fragment = context
        .fragment()
        .map_err(|err| format!("failed to create fragment: {err}"))?;

    // Name the engine's Quent Query after the StarRocks ids before build() opens it, so the
    // telemetry of this fragment and of its peers on other CNs share one query group.
----
            .map_err(|err| format!("failed to declare the broadcast output mode: {err}"))?;
    } else if !request.hash_keys.is_empty() && request.outputs.len() > 1 {
        for &key in &request.hash_keys {
            let key = u32::try_from(key).map_err(|_| format!("hash key column {key} overflows"))?;
            fragment
                .declare_output_hash_key(key)
                .map_err(|err| format!("failed to declare hash key column {key}: {err}"))?;
        }
    }

    fragment
        .build(&request.plan)
        .map_err(|err| format!("failed to plan fragment: {err}"))?;

    // The fragment boundary itself: each sender's batches move into this fragment's input stream
    // as native handles. Nothing is converted, written, or copied.
    for schema in &request.stream_inputs {
        let stream_id = stream_id_of(schema.node_id)?;
        let senders = request
            .inputs
            .iter()
            .find(|(node_id, _)| *node_id == schema.node_id)
            .map(|(_, senders)| senders.as_slice())
            .unwrap_or_default();
        for slot in senders {
            let (park_id, sender_stream) = parked_slots
                .get(slot)
                .copied()
                .ok_or_else(|| format!("no parked sender output for {slot:?}"))?;
            let sender = parked
                .get_mut(&park_id)
                .ok_or_else(|| format!("parked fragment vanished under {slot:?}"))?;
            let sender_id = u32::try_from(slot.sender_id)
                .map_err(|_| format!("negative sender id {}", slot.sender_id))?;
            let moved = fragment
                .relay_from(&mut sender.fragment, sender_stream, stream_id, sender_id)
                .map_err(|err| format!("failed to relay sender {sender_id}: {err}"))?;
            // This destination's stream is drained; release its claim (the fragment drops with
            // the last claim, freeing the GPU batches).
            release_slot(parked, parked_slots, poisoned, slot)?;
            info!(
                stream_id,
                sender_id,
                batches = moved,
                "relayed native batches across a fragment boundary"
            );
        }
    }

    // Remote senders: their packed batches already sit in this CN's staging arena. Push each
    // (deep copy into pool memory), release its lease immediately — copy-out-on-arrival makes
    // that safe — then close the sender.
    for (node_id, sender_id, batches) in &request.remote_inputs {
        let stream_id = stream_id_of(*node_id)?;
        let sender = u32::try_from(*sender_id)
            .map_err(|_| format!("negative remote sender id {sender_id}"))?;
        for batch in batches {
            let staged = sirius::PackedBatch {
                metadata: batch.metadata.clone(),
                offset: batch.offset,
                len: batch.len,
                // push_packed never reads the count; the receiver consumed it before build()
                // through declare_input_cardinality.
                rows: batch.rows.unwrap_or(0),
            };
            fragment.push_packed(stream_id, &staged).map_err(|err| {
                format!(
                    "failed to push a staged remote batch from sender {sender_id} into stream \
                     {stream_id}: {err}"
                )
            })?;
            if batch.len > 0 {
                context.staging_release(batch.offset).map_err(|err| {
                    format!(
                        "failed to release the staging lease at offset {} after pushing it: {err}",
                        batch.offset
                    )
                })?;
                released.insert(batch.offset);
            }
        }
        fragment.close_input(stream_id, sender).map_err(|err| {
            format!("failed to close remote sender {sender_id} on stream {stream_id}: {err}")
        })?;
        info!(
            stream_id,
            sender_id,
            batches = batches.len(),
            bytes = batches.iter().map(|batch| batch.len).sum::<u64>(),
            "received remote batches"
        );
    }

    fragment
        .run()
        .map_err(|err| format!("failed to execute fragment: {err}"))?;

    if !request.outputs.is_empty() {
        // Park ONCE; each destination claims (park id, its stream). A duplicate slot would let
        // two claims race over one stream -- refuse before inserting anything.
        let park_id = *next_park_id;
        *next_park_id += 1;
        for (stream, slot) in request.outputs.iter().enumerate() {
            if parked_slots.contains_key(slot) {
                return Err(format!(
                    "duplicate destination slot {slot:?} in one sender fan-out"
                ));
            }
            parked_slots.insert(slot.clone(), (park_id, stream as u64));
        }
        parked.insert(
            park_id,
            ParkedOutput {
                fragment,
                outstanding: request.outputs.len(),
            },
        );
        return Ok(None);
    }
    {
        // `into_arrow` drains the stream and drops the context-referencing wrapper here, on the
        // engine thread, returning owned batches whose buffers are released via their own Arrow C
        // release callbacks — independent of the context. So they are safe to send to, and drop
        // on, the caller's thread.
        fragment
            .into_arrow()
            .map(|result| Some(FragmentResult::new(result.batches)))
            .map_err(|err| err.to_string())
    }
}

/// Engine-side stream id for a receiver exchange node. The node id addresses the stream, so the
/// two sides of a boundary agree without a separate allocation table.
fn stream_id_of(node_id: i32) -> Result<u64, String> {
    u64::try_from(node_id).map_err(|_| format!("negative exchange node id {node_id}"))
}

/// Brings up a [`SiriusContext`] from an optional config path (built-in defaults when `None`).
fn build_context(config: Option<PathBuf>) -> Result<SiriusContext, String> {
    let context = match config {
        Some(path) => SiriusContext::from_config_file(&path),
        None => SiriusContext::new(),
    }
    .map_err(|err| format!("failed to bring up Sirius engine: {err}"))?;
    info!("Sirius engine context created");
    Ok(context)
}

impl SiriusEngine {
    /// Sends one request to the engine thread and blocks for its answer.
    fn engine_call<T>(
        &self,
        make_request: impl FnOnce(Sender<Result<T, String>>) -> EngineRequest,
    ) -> Result<T, String> {
        let (respond_tx, respond_rx) = channel();
        self.requests
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .as_ref()
            .ok_or_else(|| "sirius-engine is shutting down".to_string())?
            .send(make_request(respond_tx))

  std::size_t moved = 0;
  while (auto batch = source.impl_->session().pull(source_stream_id)) {
    // Registered before the push so the placement's `queued` precedes the receiver's `packaged`;
    // this is where the batch's park on the sender's output stream ends.
    telemetry::batch_telemetry_registry::instance().on_stream_hop(
      *batch, telemetry::batch_origin::stream_relayed);
    if (!impl_->session().push(input_stream_id, *batch)) {
      throw sirius::invalid_input_exception("Fragment: input stream " +
                                            std::to_string(input_stream_id) +
                                            " refused a batch; it had already ended");
    }
    ++moved;
  }
  impl_->session().close_input(input_stream_id, sender_id);
  return moved;
}

namespace {
/// chunked_pack gather granularity. Every `next()` span must be exactly this long, so a lease is
/// the payload plus one chunk of slack for the final span. 1 MiB is cudf's minimum.
constexpr std::size_t kPackChunkBytes = 8u << 20;
}  // namespace

std::unique_ptr<std::vector<std::uint8_t>> Fragment::export_packed(std::uint64_t stream_id,
                                                                   std::uint64_t& offset,
                                                                   std::uint64_t& length,
                                                                   std::uint64_t& rows)
{
  if (!impl_->built) {
    throw sirius::invalid_input_exception("Fragment: build() must run before export_packed()");
  }
  auto& arena = sirius::exec::exchange_staging_arena::require(impl_->ctx.staging_arena.get());

  offset     = 0;
  length     = 0;
  rows       = 0;
  auto batch = impl_->session().pull(stream_id);
  if (!batch) { return nullptr; }

  // The shared lock holds residency and immutability for the whole pack; it releases when this
  // scope ends, after the packing stream has been synchronized and the data lives in the lease.
  auto read_only = (*batch)->to_read_only();
  if (read_only.get_current_tier() != cucascade::memory::Tier::GPU) {
    throw sirius::invalid_input_exception(
      "Fragment: batch on output stream " + std::to_string(stream_id) +
      " is not GPU-resident; exporting a spilled batch is not supported yet");
  }
  auto view   = sirius::get_cudf_table_view(read_only);
  auto* space = read_only.get_memory_space();
  if (space == nullptr) {
    throw sirius::invalid_input_exception("Fragment: batch on output stream " +
                                          std::to_string(stream_id) + " has no memory space");
  }
  rows = static_cast<std::uint64_t>(view.num_rows());

  auto stream = cudf::get_default_stream();
  // STREAM-LINEAGE: order the pack's gather after the batch's writer.
  if (cudaEvent_t writer = read_only.get_writer_event()) {
    if (auto err = cudaStreamWaitEvent(stream.value(), writer, 0); err != cudaSuccess) {
      throw sirius::internal_exception("Fragment: cudaStreamWaitEvent failed: {}",
                                       cudaGetErrorString(err));
    }
  }

  auto packer =
    cudf::chunked_pack::create(view, kPackChunkBytes, stream, space->get_default_allocator());
  const std::uint64_t total = packer->get_total_contiguous_size();

  // A zero-row batch packs to a metadata-only frame: no payload, no lease. The wire contract
  // says offset==0 with length==0 means "no lease exists for this batch", so the receiver never
  // releases it — leasing here would orphan kPackChunkBytes of arena per empty batch, and one
  // orphaned lease pins staging space for the process lifetime.
  if (total == 0) { return packer->build_metadata(); }

  // Each next() span is a full chunk long and starts where the previous copy ended, so the
  // final span can reach up to one chunk past the payload — hence the slack.
  const auto lease_offset = arena.lease(total + kPackChunkBytes);
  // GPU pool -> staging lease as a DataBatch in_transit on the lease; a throw below releases
  // the lease, which settles and destructs it.
  auto* arena_probe = arena.probe();
  if (arena_probe != nullptr) {
    arena_probe->on_pack_started(lease_offset, space->get_id(), total);
  }
  std::unique_ptr<std::vector<std::uint8_t>> metadata;
  try {
    auto* lease         = reinterpret_cast<std::uint8_t*>(arena.base()) + lease_offset;
    std::size_t written = 0;
    while (packer->has_next()) {
      written += packer->next(cudf::device_span<std::uint8_t>(lease + written, kPackChunkBytes));
    }
    if (written != total) {
      throw sirius::internal_exception(
        "Fragment: chunked_pack wrote {} of {} bytes for output stream {}",
        written,
        total,
        stream_id);
    }
    metadata = packer->build_metadata();
    // The caller transmits from the lease the moment this returns.
    stream.synchronize();
    if (arena_probe != nullptr) { arena_probe->on_pack_completed(lease_offset); }
  } catch (...) {
    arena.release(lease_offset);
    throw;
  }
  offset = lease_offset;
  length = total;
  return metadata;
}

